(function() {
  const WHATSAPP_NUMBER = "50487460497";
  const ASSETS = {"marble": "data:image/jpeg;base64,", "logoCircle": "data:image/png;base64,", "logoTooth": "data:image/png;base64,", "draYelsy": "data:image/jpeg;base64,", "drCarlos": "data:image/jpeg;base64,", "teamExperts": "data:image/jpeg;base64,", "teamHonduras": "data:image/jpeg;base64,", "teamConsulta": "data:image/jpeg;base64,", "teamPaciente": "data:image/jpeg;base64,", "teamCool": "data:image/jpeg;base64,", "atencionClinica": "data:image/jpeg;base64,", "ortodonciaInfantil": "data:image/jpeg;base64,", "alineadores": "data:image/jpeg;base64,", "bracketsAutoligables": "data:image/jpeg;base64,", "iconTooth": "data:image/jpeg;base64,", "iconMirrorProbe": "data:image/jpeg;base64,", "iconOrthoTools": "data:image/jpeg;base64,"};
  const APPT_TYPES = [{"id": "valoracion", "label": "Valoración y Diagnóstico", "sub": "Evaluación integral inicial", "doc": "Dr. Carlos Fajardo"}, {"id": "ortodoncia", "label": "Ortodoncia / Brackets", "sub": "Metálicos, estéticos o autoligables", "doc": "Dra. Yelsy Funes"}, {"id": "alineadores", "label": "Alineadores Invisibles", "sub": "Ortodoncia discreta y moderna", "doc": "Dra. Yelsy Funes"}, {"id": "infantil", "label": "Ortodoncia Infantil", "sub": "Ortopedia maxilofacial para niños", "doc": "Dra. Yelsy Funes"}, {"id": "limpieza", "label": "Limpieza y Encías", "sub": "Profilaxis y salud periodontal", "doc": "Dr. Carlos Fajardo"}, {"id": "diseno", "label": "Diseño de Sonrisa", "sub": "Estética dental personalizada", "doc": "Dr. Carlos Fajardo"}, {"id": "cirugia", "label": "Extracción / Cirugía Oral", "sub": "Atención segura y profesional", "doc": "Dr. Carlos Fajardo"}, {"id": "protesis", "label": "Prótesis y Restauraciones", "sub": "Rehabilitación funcional y estética", "doc": "Dr. Carlos Fajardo"}, {"id": "control", "label": "Control Mensual", "sub": "Seguimiento de tratamiento activo", "doc": "Dra. Yelsy Funes"}];
  const GALLERY_ITEMS = [{"img": "teamExperts", "title": "Equipo F&F Dental Clinic", "sub": "Dr. Carlos Fajardo y Dra. Yelsy Funes — Tegucigalpa"}, {"img": "teamConsulta", "title": "Atención Clínica Especializada", "sub": "Diagnóstico profesional y cuidado periodontal"}, {"img": "ortodonciaInfantil", "title": "Ortodoncia Infantil", "sub": "Dra. Yelsy Funes — Espacios cómodos y seguros"}, {"img": "alineadores", "title": "Alineadores Dentales", "sub": "Cómodos, removibles y de última tecnología"}, {"img": "bracketsAutoligables", "title": "Brackets Autoligables", "sub": "Opciones cerámicas estéticas y metálicas"}, {"img": "atencionClinica", "title": "Control Mensual", "sub": "Seguimiento cercano en cada etapa de tu sonrisa"}, {"img": "teamHonduras", "title": "Orgullosamente en Centro Morazán", "sub": "Torre #2, Tegucigalpa — Salud bucal para Honduras"}, {"img": "teamPaciente", "title": "Pacientes Felices", "sub": "Trato humano, cercano y resultados reales"}];

  const state = {
    selectedType: APPT_TYPES[0].id,
    selectedDoctor: "Sin preferencia",
    patientName: "",
    preferredTime: "Mañana (8:00 AM - 12:00 PM)",
    activeArea: "all"
  };

  document.querySelectorAll("[data-asset]").forEach((el) => {
    const key = el.getAttribute("data-asset");
    if (ASSETS[key]) {
      el.src = ASSETS[key];
    }
  });

  function getSelectedTypeObj() {
    return APPT_TYPES.find((t) => t.id === state.selectedType) || APPT_TYPES[0];
  }

  function buildWhatsAppMessage() {
    const t = getSelectedTypeObj();
    const nombre = state.patientName.trim();
    const saludo = nombre ? `Hola F&F Dental Clinic, mi nombre es ${nombre}.` : "Hola F&F Dental Clinic.";
    const docPart = state.selectedDoctor && state.selectedDoctor !== "Sin preferencia"
      ? ` Me gustaría atenderme con ${state.selectedDoctor}.`
      : "";
    return `${saludo} Quisiera agendar una cita en su clínica de Tegucigalpa (Centro Morazán, Torre #2) para: ${t.label}.${docPart} Horario de preferencia: ${state.preferredTime}.`;
  }

  function buildWhatsAppUrl() {
    return `https://wa.me/${WHATSAPP_NUMBER}?text=${encodeURIComponent(buildWhatsAppMessage())}`;
  }

  function renderApptChips(containerId) {
    const container = document.getElementById(containerId);
    if (!container) return;
    container.innerHTML = "";
    APPT_TYPES.forEach((item) => {
      const btn = document.createElement("button");
      btn.type = "button";
      btn.className = "appt-chip" + (state.selectedType === item.id ? " selected" : "");
      btn.innerHTML = `<strong>${item.label}</strong><span>${item.sub}</span>`;
      btn.addEventListener("click", () => {
        state.selectedType = item.id;
        syncBookingUI();
      });
      container.appendChild(btn);
    });
  }

  function syncBookingUI() {
    renderApptChips("apptTypeGrid");
    renderApptChips("modalApptGrid");

    const msg = buildWhatsAppMessage();
    const url = buildWhatsAppUrl();

    const preview = document.getElementById("waMessagePreview");
    if (preview) preview.textContent = msg;

    const modalPreview = document.getElementById("modalWaPreview");
    if (modalPreview) modalPreview.textContent = msg;

    const mainBtn = document.getElementById("waDirectBtn");
    if (mainBtn) mainBtn.href = url;

    const modalBtn = document.getElementById("modalWaBtn");
    if (modalBtn) modalBtn.href = url;

    const docSelect = document.getElementById("doctorSelect");
    if (docSelect && docSelect.value !== state.selectedDoctor) {
      docSelect.value = state.selectedDoctor;
    }
    const modalDocSelect = document.getElementById("modalDoctorSelect");
    if (modalDocSelect && modalDocSelect.value !== state.selectedDoctor) {
      modalDocSelect.value = state.selectedDoctor;
    }
  }

  document.querySelectorAll(".area-tab").forEach((tab) => {
    tab.addEventListener("click", () => {
      state.activeArea = tab.getAttribute("data-area");
      document.querySelectorAll(".area-tab").forEach((b) => b.classList.remove("active"));
      tab.classList.add("active");
      document.querySelectorAll(".service-card").forEach((card) => {
        const cat = card.getAttribute("data-category");
        card.style.display = (state.activeArea === "all" || cat === state.activeArea) ? "flex" : "none";
      });
    });
  });

  const nameInput = document.getElementById("patientNameInput");
  if (nameInput) {
    nameInput.addEventListener("input", (e) => {
      state.patientName = e.target.value;
      syncBookingUI();
    });
  }

  const doctorSelect = document.getElementById("doctorSelect");
  if (doctorSelect) {
    doctorSelect.addEventListener("change", (e) => {
      state.selectedDoctor = e.target.value;
      syncBookingUI();
    });
  }

  const timeSelect = document.getElementById("timeSelect");
  if (timeSelect) {
    timeSelect.addEventListener("change", (e) => {
      state.preferredTime = e.target.value;
      syncBookingUI();
    });
  }

  const modalDoctorSelect = document.getElementById("modalDoctorSelect");
  if (modalDoctorSelect) {
    modalDoctorSelect.addEventListener("change", (e) => {
      state.selectedDoctor = e.target.value;
      syncBookingUI();
    });
  }

  const bookingModal = document.getElementById("bookingModal");
  function openBookingModal(typeId, doctorName) {
    if (typeId) state.selectedType = typeId;
    if (doctorName) state.selectedDoctor = doctorName;
    syncBookingUI();
    if (bookingModal) bookingModal.classList.add("open");
  }

  function closeBookingModal() {
    if (bookingModal) bookingModal.classList.remove("open");
  }

  document.querySelectorAll("[data-open-booking]").forEach((btn) => {
    btn.addEventListener("click", (e) => {
      e.preventDefault();
      const t = btn.getAttribute("data-appt-type") || "";
      const d = btn.getAttribute("data-doctor") || "";
      openBookingModal(t, d);
    });
  });

  const closeModalBtn = document.getElementById("closeBookingModal");
  if (closeModalBtn) closeModalBtn.addEventListener("click", closeBookingModal);
  if (bookingModal) {
    bookingModal.addEventListener("click", (e) => {
      if (e.target === bookingModal) closeBookingModal();
    });
  }

  const galleryGrid = document.getElementById("galleryGrid");
  const lightboxModal = document.getElementById("lightboxModal");
  const lightboxImg = document.getElementById("lightboxImg");
  const lightboxTitle = document.getElementById("lightboxTitle");
  const lightboxSub = document.getElementById("lightboxSub");

  if (galleryGrid) {
    GALLERY_ITEMS.forEach((item) => {
      const card = document.createElement("div");
      card.className = "gallery-item";
      card.innerHTML = `
        <img src="${ASSETS[item.img]}" alt="${item.title}">
        <div class="gallery-overlay">
          <strong>${item.title}</strong>
          <span>${item.sub}</span>
        </div>
      `;
      card.addEventListener("click", () => {
        if (lightboxImg) lightboxImg.src = ASSETS[item.img];
        if (lightboxTitle) lightboxTitle.textContent = item.title;
        if (lightboxSub) lightboxSub.textContent = item.sub;
        if (lightboxModal) lightboxModal.classList.add("open");
      });
      galleryGrid.appendChild(card);
    });
  }

  const closeLightboxBtn = document.getElementById("closeLightboxModal");
  if (closeLightboxBtn) {
    closeLightboxBtn.addEventListener("click", () => lightboxModal.classList.remove("open"));
  }
  if (lightboxModal) {
    lightboxModal.addEventListener("click", (e) => {
      if (e.target === lightboxModal) lightboxModal.classList.remove("open");
    });
  }

  const menuToggle = document.getElementById("menuToggle");
  const navLinks = document.getElementById("navLinks");
  if (menuToggle && navLinks) {
    menuToggle.addEventListener("click", () => {
      navLinks.classList.toggle("open");
    });
    navLinks.querySelectorAll("a").forEach((link) => {
      link.addEventListener("click", () => navLinks.classList.remove("open"));
    });
  }

  syncBookingUI();
})();